import zipfile, re, os, sys

SRC = 'sales_data.xlsx'
TMP = 'sales_data.tmp.xlsx'


def col_letter(idx):
    s = ''
    idx += 1
    while idx:
        idx, rem = divmod(idx - 1, 26)
        s = chr(65 + rem) + s
    return s


def col_index(ref):
    n = 0
    for ch in re.match(r'([A-Z]+)', ref).group(1):
        n = n * 26 + (ord(ch) - 64)
    return n - 1


def esc(s):
    return s.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;')


zin = zipfile.ZipFile(SRC)
names = zin.namelist()

shared = []
if 'xl/sharedStrings.xml' in names:
    import xml.etree.ElementTree as ET
    M = '{http://schemas.openxmlformats.org/spreadsheetml/2006/main}'
    root = ET.fromstring(zin.read('xl/sharedStrings.xml'))
    for si in root.findall(M + 'si'):
        shared.append(''.join(t.text or '' for t in si.iter(M + 't')))


def cell_text(attrs, inner):
    t = attrs.get('t')
    if t == 's':
        m = re.search(r'<v>([^<]*)</v>', inner)
        if m:
            try:
                return shared[int(m.group(1))]
            except (ValueError, IndexError):
                return None
    elif t == 'inlineStr':
        return re.sub(r'<[^>]+>', '', inner)
    else:
        m = re.search(r'<v>([^<]*)</v>', inner)
        if m:
            return m.group(1)
    return None


wbxml = zin.read('xl/workbook.xml').decode('utf-8')
relsxml = zin.read('xl/_rels/workbook.xml.rels').decode('utf-8')
relmap = dict(re.findall(r'<Relationship\b[^>]*Id="([^"]+)"[^>]*Target="([^"]+)"', relsxml))
sheets = re.findall(r'<sheet\b[^>]*>', wbxml)
sheet_info = []
for tag in sheets:
    name = re.search(r'name="([^"]*)"', tag)
    rid = re.search(r'r:id="([^"]+)"', tag) or re.search(r'id="(rId\d+)"', tag)
    if name and rid:
        sheet_info.append((name.group(1), rid.group(1)))
print('sheets:', [s[0] for s in sheet_info])

sname, rid = sheet_info[0]
tgt = relmap.get(rid)
if not tgt:
    sys.exit('no target for ' + rid)
spath = tgt if tgt.startswith('xl/') else ('xl/' + tgt.lstrip('/'))
print('sheet path:', spath)

sheet_text = zin.read(spath).decode('utf-8')

row_re = re.compile(r'<row\b[^>]*>.*?</row>|<row\b[^>]*/>', re.S)
cell_re = re.compile(r'<c\b[^>]*>.*?</c>|<c\b[^>]*/>', re.S)

max_col = -1
rows_info = []
for m in row_re.finditer(sheet_text):
    row_xml = m.group(0)
    attrs = row_xml[:row_xml.find('>')]
    rmatch = re.search(r'\br="(\d+)"', attrs)
    rn = int(rmatch.group(1)) if rmatch else len(rows_info) + 1
    cells = []
    for cm in cell_re.finditer(row_xml):
        cxml = cm.group(0)
        cattrs = dict(re.findall(r'(\w+)\s*=\s*"([^"]*)"', cxml[:cxml.find('>')]))
        ref = cattrs.get('r')
        if not ref:
            continue
        ci = col_index(ref)
        if ci > max_col:
            max_col = ci
        cells.append((ci, cattrs, cxml))
    rows_info.append((rn, cells))
print('rows:', len(rows_info), 'max_col:', max_col)

headers = {}
for ci, cattrs, cxml in rows_info[0][1]:
    inner = cxml[cxml.find('>') + 1:]
    if cxml.rstrip().endswith('/>'):
        inner = ''
    txt = cell_text(cattrs, inner)
    if txt is not None:
        headers[ci] = str(txt).strip().lower()
print('headers:', headers)


def find_col(substrs, exclude=()):
    for ci, h in headers.items():
        if all(s in h for s in substrs) and not any(e in h for e in exclude):
            return ci
    return None


rev_col = find_col(['revenue']) or find_col(['sales'], exclude=['cost'])
prof_col = find_col(['profit'])
cost_col = find_col(['cost']) or find_col(['cogs'])
print('rev_col:', rev_col, 'prof_col:', prof_col, 'cost_col:', cost_col)
if rev_col is None:
    sys.exit('Could not locate a revenue/sales column')

new_col = max_col + 1
if new_col > 16384:
    sys.exit('no room for new column')
L = col_letter(new_col)
R = col_letter(rev_col)
print('new column:', L)

if prof_col is not None:
    P = col_letter(prof_col)
    fmt = lambda n: 'IFERROR(IF(%s%d=0,"",%s%d/%s%d),"")' % (R, n, P, n, R, n)
elif cost_col is not None:
    C = col_letter(cost_col)
    fmt = lambda n: 'IFERROR(IF(%s%d=0,"",(%s%d-%s%d)/%s%d),"")' % (R, n, R, n, C, n, R, n)
else:
    sys.exit('Need a profit or cost column')

styles_text = zin.read('xl/styles.xml').decode('utf-8') if 'xl/styles.xml' in names else None
xf_idx = 0
use_s = False
if styles_text is not None:
    if '<numFmts' in styles_text and '</numFmts>' in styles_text:
        if 'numFmtId="164"' not in styles_text:
            m = re.search(r'<numFmts\b[^>]*count="(\d+)"', styles_text)
            if m:
                styles_text = styles_text[:m.start(1)] + str(int(m.group(1)) + 1) + styles_text[m.end(1):]
            styles_text = re.sub(r'</numFmts>', '<numFmt numFmtId="164" formatCode="0.0%"/></numFmts>', styles_text, count=1)
    elif '<numFmts' in styles_text:
        styles_text = re.sub(r'<numFmts\b([^>]*)/>', r'<numFmts\1>' + '<numFmt numFmtId="164" formatCode="0.0%"/></numFmts>', styles_text, count=1)
    else:
        m = re.search(r'<styleSheet\b[^>]*>', styles_text)
        styles_text = styles_text[:m.end(0)] + '<numFmts count="1"><numFmt numFmtId="164" formatCode="0.0%"/></numFmts>' + styles_text[m.end(0):]
    cm = re.search(r'<cellXfs\b[^>]*>(.*?)</cellXfs>', styles_text, re.S)
    if cm:
        xfm = re.search(r'<xf\b[^>]*?(/?)>', cm.group(1))
        if xfm:
            base = xfm.group(0)
            attrs = base[:-2] if base.rstrip().endswith('/>') else base[:-1]
            attrs = re.sub(r'\snumFmtId="[^"]*"', '', attrs)
            attrs = re.sub(r'\sapplyNumberFormat="[^"]*"', '', attrs)
            newxf = attrs + ' numFmtId="164" applyNumberFormat="1"/>'
            styles_text = re.sub(r'</cellXfs>', newxf + '</cellXfs>', styles_text, count=1)
            cm2 = re.search(r'<cellXfs\b[^>]*count="(\d+)"', styles_text)
            if cm2:
                styles_text = styles_text[:cm2.start(1)] + str(int(cm2.group(1)) + 1) + styles_text[cm2.end(1):]
                xf_idx = int(cm2.group(1))
            else:
                xf_idx = len(re.findall(r'<xf\b', cm.group(1)))
            use_s = True

header_cell = '<c r="%s1" t="inlineStr"><is><t>Profit Margin %%</t></is></c>' % L


def data_cell(rn):
    body = '<f>%s</f>' % esc(fmt(rn))
    return '<c r="%s%d" s="%d">%s</c>' % (L, rn, xf_idx, body) if use_s else '<c r="%s%d">%s</c>' % (L, rn, body)


out = []
pos = 0
for m in row_re.finditer(sheet_text):
    out.append(sheet_text[pos:m.start()])
    pos = m.end()
    row_xml = m.group(0)
    attrs = row_xml[:row_xml.find('>')]
    rmatch = re.search(r'\br="(\d+)"', attrs)
    rn = int(rmatch.group(1)) if rmatch else None
    close = row_xml.rfind('</row>')
    if rn == 1:
        if close != -1:
            out.append(row_xml[:close] + header_cell + row_xml[close:])
        else:
            out.append(row_xml[:-2] + '>' + header_cell + '</row>')
    elif rn is not None and rn >= 2 and close != -1:
        out.append(row_xml[:close] + data_cell(rn) + row_xml[close:])
    else:
        out.append(row_xml)
out.append(sheet_text[pos:])
new_sheet = ''.join(out)

wb2 = wbxml
if 'calcPr' not in wb2:
    wb2 = re.sub(r'</sheets>', '</sheets><calcPr calcId="0" fullCalcOnLoad="1"/>', wb2, count=1)

zout = zipfile.ZipFile(TMP, 'w')
for item in zin.infolist():
    if item.filename.endswith('/'):
        continue
    data = zin.read(item.filename)
    if item.filename == spath:
        data = new_sheet.encode('utf-8')
    elif item.filename == 'xl/styles.xml' and styles_text is not None:
        data = styles_text.encode('utf-8')
    elif item.filename == 'xl/workbook.xml':
        data = wb2.encode('utf-8')
    elif item.filename == 'xl/calcChain.xml':
        continue
    zout.writestr(item, data)
zout.close()
zin.close()
os.replace(TMP, SRC)
print('OK: added header %s1 "Profit Margin %%", formulas rows 2..%d' % (L, rows_info[-1][0]))

